import java.util.*;

class Solution {
    public int[] twoLonely(int[] nums) {
        int x = 0;
        for (int v : nums) x ^= v;   // x = a ^ b
        int low = x & -x;            // a and b differ on this bit
        int a = 0;
        for (int v : nums) {
            if ((v & low) != 0) a ^= v; // group with the bit set; pairs cancel
        }
        int b = x ^ a;
        return new int[]{Math.min(a, b), Math.max(a, b)};
    }
}

