class Solution:
    def twoLonely(self, nums: List[int]) -> List[int]:
        x = 0
        for v in nums: x ^= v
        low = x & -x; a = 0
        for v in nums:
            if v & low: a ^= v
        b = x ^ a
        return [min(a, b), max(a, b)]

